const translations={en:{navInteractions:'Controls',interactionTitle:'Not just adapted. Redesigned for play.',interactionIntro:'The top display shows the action, while the touchscreen hosts a dedicated security center. Interaction is designed for the handheld format, not simply a PC game squeezed onto one display.',interaction1:'Direct camera selection',interaction1Text:'Tap rooms on the lower-screen map to change the monitored camera on the upper screen.',interaction2:'Flashlights and mask',interaction2Text:'Access the hallway and vent lights and equip the mask using the security controls.',interaction3:'Tablet and surveillance',interaction3Text:'Open or close the tablet, inspect cameras, and manage surveillance across both screens.',interaction4:'Continue to the next night',interaction4Text:'Custom victory flow, shift report, and Continue / Game Menu controls.',interaction5:'Custom Night',interaction5Text:'A configuration interface designed to adjust animatronic AI levels directly on DSi. Functionality must be verified against the published build.',interaction6:'Custom loading screens',interaction6Text:'Loading animations, boot terminal, Game Over, victory and menu states designed for this version.',comparisonTitle:'From PC to DSi: fundamentally different architectures.',comparisonIntro:'A comparison between the PC original’s published minimum requirements and the console’s hardware. These are not directly comparable benchmarks.',reqProcessor:'Processor',reqMemory:'RAM',reqGraphics:'Published graphics requirement',reqStorage:'Storage',reqPlatform:'Platform',reqSource:'Source: official Steam requirements ↗',dsScreens:'Displays',dsTouch:'Input',dsTouchValue:'Touchscreen + buttons',dsExecution:'Runtime',dsSource:'Source: official Nintendo DSi manual (displays) ↗',approachTitle:'Behavior reverse engineering + system reimplementation + original UX',approachText:'This is not Windows software running on the console, nor simply downscaled visuals. Logic and interfaces were rebuilt for homebrew, with navigation, loading, presentation and dual-screen interactions designed for the device.',approachCaveat:'Technical note: 1 GB and 16 MB describe different hardware platforms; this comparison is not a measurement of the game’s actual memory usage.',demoResolutionValue:'250 × 370 (cropped)',navGallery:'Gallery',navDemo:'Video',demoTitle:'Watch the project in action.',demoIntro:'Gameplay recorded on a computer using a Nintendo DSi emulator. See the dual-screen interface, menus, and the experience developed.',videoFallback:'Your browser does not support HTML5 video.',videoTag:'REAL PROJECT FOOTAGE · PC EMULATOR',videoDownload:'DOWNLOAD MP4 ↗',demoAsideTitle:'One console. Two screens. One challenge.',demoAsideText:'This demonstration was recorded on a computer emulator, not on physical Nintendo DSi hardware.',demoPlatform:'Target platform',demoCapture:'Recording environment',demoCaptureValue:'Emulator / computer',demoResolution:'Video resolution',demoLength:'Duration',demoNote:'On-demand playback: the video does not autoplay and loads only when requested.',galleryTitle:'Real project screenshots.',galleryIntro:'Screenshots provided by the developer, preserving the two vertically stacked DSi displays.',shot1:'Main menu',shot2:'System boot',shot3:'Office',shot4:'Camera map',shot5:'6 AM victory',navProject:'Project',navEngineering:'Engineering',navTimeline:'Timeline',navContact:'Contact',heroLead:'A reverse-engineered reimplementation with a bespoke interface, adapted mechanics, and native interaction across both Nintendo DSi XL screens.',source:'VIEW SOURCE ON GITHUB ↗',explore:'WATCH GAMEPLAY ▶',metricRelease:'RELEASE',metricScreens:'INTEGRATED SCREENS',metricStack:'PROGRAMMING',metricTarget:'TARGET HARDWARE',projectTitle:'A challenge beyond the game.',projectText:'Beyond reproducing the original, we reconstructed behaviors and designed a new DSi experience: menus, transitions, custom loading screens, and controls built around two displays.',feature1:'Camera system',feature1Text:'Interactive tablet, room switching, lighting, and a dual-screen interface.',feature2:'Animatronic AI',feature2Text:'Behaviors, movement routes, reaction windows, and night balancing.',feature3:'UI and state systems',feature3Text:'Menus, introduction, cutscenes, loading, Game Over, and victory.',engineeringTitle:'Not a direct port. A reconstruction.',challengeTitle:'Engineering challenges',challengeText:'We studied the original PC gameplay, rebuilt systems in C/C++, and created custom interfaces, loading transitions and interaction flows for a handheld with limited memory and two displays.',timelineTitle:'Iterative evolution.',t1:'Earlier stability milestone.',t2:'Transition fixes, interfaces, audio, and result screens.',t3:'Intro flow, Custom Night, loading, and reaction-time adjustments.',t4:'Release prepared for public project presentation.',contactTitle:'From project to career.',contactText:'This project showcases continuous learning, logical reasoning, debugging, optimization, and the ability to turn complex requirements into working software.',footer:'Independent, non-commercial project. Characters and assets belong to their respective owners.'}};translations.en.socialInvite='Enjoyed the project? Follow for new videos and updates.';translations.en.portfolioHome='MAIN PORTFOLIO ?';translations.en.socialYoutube='FOLLOW ON YOUTUBE ↗';translations.en.socialInstagram='FOLLOW ON INSTAGRAM ↗';translations.en.feedbackCta='SEND FEEDBACK / BUG ↗';const original={};document.querySelectorAll('[data-i18n]').forEach(el=>original[el.dataset.i18n]=el.textContent);
const pageMetaDescription=document.querySelector('meta[name="description"]');
const pageDefaults={title:document.title,description:pageMetaDescription?pageMetaDescription.content:''};
const LANGUAGES=['pt-BR','en','es','fr'];
const languageButtons=document.querySelectorAll('[data-lang-option]');
const languageStorageKey='fnaf-dsi-docs-language';
let lang='pt-BR';

/* Em portugues nao ha dict: o texto que ja esta no HTML e a fonte. Nos outros
   idiomas, uma chave ausente cai no portugues em vez de apagar o element. */
function valueFor(key, fallback) {
  if (lang === 'pt-BR') return fallback;
  const dict = translations[lang];
  return dict && dict[key] !== undefined ? dict[key] : fallback;
}

function applyLanguage(code) {
  if (LANGUAGES.includes(code)) lang = code;
  document.documentElement.lang = lang === 'pt-BR' ? 'pt-BR' : lang;
  document.querySelectorAll('[data-i18n]').forEach(el=>{
    if (el === heroEyebrow) return;
    const key = el.dataset.i18n;
    const value = valueFor(key, original[key] ?? el.textContent);
    if (value !== undefined) el.textContent = value;
  });
  if (heroEyebrowText) heroEyebrowText.nodeValue = ` ${valueFor('heroEyebrow', original.heroEyebrow)} `;
  document.title = valueFor('pageTitle', pageDefaults.title);
  if (pageMetaDescription) pageMetaDescription.content = valueFor('pageDescription', pageDefaults.description);
  for (const [el, originalValue] of originalAttributes) {
    const altKey = el.dataset.i18nAlt;
    const labelKey = el.dataset.i18nAriaLabel;
    if (altKey) el.setAttribute('alt', valueFor(altKey, originalValue.alt));
    if (labelKey) {
      const value = valueFor(labelKey, originalValue.ariaLabel);
      if (value) el.setAttribute('aria-label', value);
    }
  }
  visitorCounterImage.alt = valueFor('counterAlt', 'Contador de visualizações do site');
  if (visitorCounterFallback.hidden === false) {
    visitorCounterFallback.textContent = valueFor('counterUnavailable', 'Contador de visualizações indisponível');
  }
  languageButtons.forEach((button)=>button.setAttribute('aria-pressed', String(button.dataset.langOption === lang)));
  try { localStorage.setItem(languageStorageKey, lang); } catch (error) { if (error.name !== 'SecurityError') throw error; }
  const pageUrl = new URL(window.location.href);
  pageUrl.searchParams.set('lang', lang);
  history.replaceState(null, '', pageUrl);
  document.dispatchEvent(new CustomEvent('site-language-change', { detail: { language: lang } }));
}

/* Sem ?lang= na URL e sem escolha gravada, o navegador decide: quem abre de Buenos
   Aires ve espanhol, quem abre de Paris ve frances. Um pt de qualquer pais continua
   em pt-BR, que e a unica variante portuguesa que temos. */
function detectLanguage() {
  const preferred = navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language];
  for (const tag of preferred) {
    if (!tag) continue;
    const base = String(tag).toLowerCase().split('-')[0];
    if (base === 'pt') return 'pt-BR';
    const match = LANGUAGES.find((code) => code.toLowerCase() === base);
    if (match) return match;
  }
  return 'pt-BR';
}

function readStoredLanguage() {
  try {
    const stored = localStorage.getItem(languageStorageKey);
    return LANGUAGES.includes(stored) ? stored : null;
  } catch (error) {
    if (error.name !== 'SecurityError') throw error;
    return null;
  }
}

