for (const [selector, entries] of staticTextTranslations) {
  /* O HTML de index ja traz data-i18n em alguns rotulos (updatesLabel e um deles).
     Contar essas casas no indice empurrava todos os rotulos seguintes uma posicao
     para tras: a secao de atualizacoes ganhava "02 / JOGABILIDADE" e o ultimo
     rotulo sobrava sem chave. Quem ja tem chave pertence ao dict normal. */
  let position = 0;
  document.querySelectorAll(selector).forEach((element) => {
    if (element.dataset.i18n) return;
    const entry = entries[position];
    position += 1;
    if (!entry) return;
    const [key, portuguese, english] = entry;
    element.dataset.i18n = key;
    original[key] = portuguese;
    translations.en[key] = english;
  });
}

const heroEyebrow = document.querySelector('.hero .eyebrow');
const heroEyebrowText = Array.from(heroEyebrow.childNodes).find(node => node.nodeType === Node.TEXT_NODE);
if (heroEyebrowText) {
  original.heroEyebrow = 'PROJETO HOMEBREW / NINTENDO DSi XL / V19.7';
  heroEyebrow.dataset.i18n = 'heroEyebrow';
}

const originalAttributes = new Map();
document.querySelectorAll('[data-i18n-alt],[data-i18n-aria-label]').forEach(el => {
  originalAttributes.set(el, { alt: el.getAttribute('alt'), ariaLabel: el.getAttribute('aria-label') });
});

languageButtons.forEach((button) => {
  button.addEventListener('click', () => applyLanguage(button.dataset.langOption));
});

const requestedLanguage = new URLSearchParams(window.location.search).get('lang');
applyLanguage(LANGUAGES.includes(requestedLanguage) ? requestedLanguage : readStoredLanguage() || detectLanguage());
